from solution import even_bit_set_number


def test_issue_example_10():
    """Check example assert even_bit_set_number(10) == 10."""
    assert even_bit_set_number(10) == 10  # 0b1010 | 0b1010 = 0b1010 (10 stays 10)


def test_issue_two_unchanged():
    """Check rule set all even bits leaves 2-bit value 2 unchanged."""
    assert even_bit_set_number(2) == 2  # 0b10 | 0b10 = 0b10 (2|2=2)


def test_issue_three_unchanged():
    """Check rule set all even bits leaves 2-bit value 3 unchanged."""
    assert even_bit_set_number(3) == 3  # 0b11 | 0b10 = 0b11 (3|2=3)


def test_issue_eight_becomes_ten():
    """Check rule set all even bits turns 8 into 10."""
    assert even_bit_set_number(8) == 10  # 0b1000 | 0b0010 = 0b1010 (8|2=10)


def test_issue_nine_becomes_eleven():
    """Check rule set all even bits turns 9 into 11."""
    assert even_bit_set_number(9) == 11  # 0b1001 | 0b0010 = 0b1011 (9|2=11)


def test_issue_twelve_becomes_fourteen():
    """Check rule set all even bits turns 12 into 14."""
    assert even_bit_set_number(12) == 14  # 0b1100 | 0b0010 = 0b1110 (12|2=14)


def test_issue_thirtytwo_becomes_fortytwo():
    """Check rule set all even bits turns 32 into 42."""
    assert even_bit_set_number(32) == 42  # 0b100000 | 0b001010 = 0b101010 (32|10=42)


def test_issue_zero_unchanged():
    """Check rule set all even bits leaves 0 unchanged."""
    assert even_bit_set_number(0) == 0  # 0b0 | 0b0 = 0b0 (0 stays 0)


def test_contract_never_clears_bits():
    """Check contract that setting bits never clears input bits."""
    assert even_bit_set_number(12) & 12 == 12  # 0b1110 & 0b1100 = 0b1100 (14&12=12)


def test_contract_second_application_stable():
    """Check contract that setting even bits twice is stable."""
    assert even_bit_set_number(even_bit_set_number(8)) == 10  # inner 0b1000|0b0010=0b1010=10 outer 0b1010|0b1010=0b1010=10


def test_contract_returns_int():
    """Check contract that public interface even_bit_set_number(n) returns int."""
    assert isinstance(even_bit_set_number(10), int)  # 0b1010 stays 0b1010 so type is int
